function validate([startPos, homePos, rowCosts, colCosts]) {
  const m = rowCosts.length, n = colCosts.length;
  if (m < 1 || m > 100000) return 'rowCosts needs 1 to 100000 values.';
  if (n < 1 || n > 100000) return 'colCosts needs 1 to 100000 values.';
  const ok = v => Number.isInteger(v) && v >= 0 && v <= 10000;
  if (!rowCosts.every(ok) || !colCosts.every(ok)) return 'Every cost is an integer from 0 to 10000.';
  if (startPos.length !== 2 || homePos.length !== 2) return 'startPos and homePos each hold [row, column].';
  for (const [r, c] of [startPos, homePos]) {
    if (!Number.isInteger(r) || r < 0 || r >= m) return 'Each row must be between 0 and rowCosts.length - 1.';
    if (!Number.isInteger(c) || c < 0 || c >= n) return 'Each column must be between 0 and colCosts.length - 1.';
  }
  return null;
}

