function minCost(startPos, homePos, rowCosts, colCosts) {
  let [row, col] = startPos;
  const [homeRow, homeCol] = homePos;
  let cost = 0;

  while (row !== homeRow) {
    row += row < homeRow ? 1 : -1;
    cost += rowCosts[row];
  }

  while (col !== homeCol) {
    col += col < homeCol ? 1 : -1;
    cost += colCosts[col];
  }

  return cost;
}

