function minCost(startPos, homePos, rowCosts, colCosts) {
  // Dijkstra over every cell of the grid (fine for the tiny grids it is tested on).
  const m = rowCosts.length, n = colCosts.length;
  const dist = Array.from({ length: m }, () => new Array(n).fill(Infinity));
  const done = Array.from({ length: m }, () => new Array(n).fill(false));
  dist[startPos[0]][startPos[1]] = 0;
  for (let round = 0; round < m * n; round++) {
    let br = -1, bc = -1;
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++)
      if (!done[r][c] && (br < 0 || dist[r][c] < dist[br][bc])) { br = r; bc = c; }
    done[br][bc] = true;
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const r = br + dr, c = bc + dc;
      if (r < 0 || c < 0 || r >= m || c >= n) continue;
      const step = dr !== 0 ? rowCosts[r] : colCosts[c];
      if (dist[br][bc] + step < dist[r][c]) dist[r][c] = dist[br][bc] + step;
    }
  }
  return dist[homePos[0]][homePos[1]];
}

