function generate(rand, size) {
  const m = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 6);
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 6);
  const top = size === 'large' ? 10000 : (rand() < 0.3 ? 1 : 12);
  const cost = () => (rand() < 0.15 ? 0 : Math.floor(rand() * (top + 1)));
  const rowCosts = Array.from({ length: m }, cost);
  const colCosts = Array.from({ length: n }, cost);
  const pick = k => Math.floor(rand() * k);
  let startPos = [pick(m), pick(n)];
  let homePos = [pick(m), pick(n)];
  if (size === 'large' && rand() < 0.7) {
    // Put the two cells near opposite corners so the trip is long.
    startPos = [pick(10), m - 1 - pick(10)];
    homePos = [m - 1 - pick(10), pick(10)];
    startPos[1] = Math.min(startPos[1], n - 1);
  }
  if (size === 'small' && rand() < 0.1) homePos = startPos.slice();
  return [startPos, homePos, rowCosts, colCosts];
}
